<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{{ $booking->booking_no }} · Quotation</title>
<style>
*{box-sizing:border-box}:root{--navy:#103f79;--navy-dark:#0b2d58;--ink:#13233d;--muted:#66758a;--line:#d9e3ef;--soft:#f5f8fc}
body{margin:0;background:#edf3f8;color:var(--ink);font-family:Arial,Helvetica,sans-serif}.actions{width:210mm;margin:18px auto 12px;display:flex;gap:8px}.btn{border:0;border-radius:8px;background:var(--navy);color:#fff;font-weight:800;padding:11px 18px;cursor:pointer}.sheet{width:210mm;min-height:297mm;margin:0 auto 28px;background:#fff;padding:14mm 13mm 12mm;box-shadow:0 8px 30px rgba(15,41,70,.13)}
.doc-header{display:grid;grid-template-columns:105px 1fr 290px;gap:20px;align-items:start;padding-bottom:18px;border-bottom:3px solid var(--navy)}.logo-wrap{width:90px;height:90px;display:flex;align-items:center;justify-content:center}.logo-wrap img{max-width:90px;max-height:90px;object-fit:contain}.logo-fallback{width:74px;height:74px;border:2px solid var(--line);border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:900;color:var(--navy)}.brand-name{font-size:27px;line-height:1.05;font-weight:900;color:var(--navy)}.brand-legal{font-size:13px;font-weight:800;margin-top:4px}.brand-contact{font-size:11px;line-height:1.55;color:#34445d;margin-top:9px}.doc-meta{border-left:1px solid var(--line);padding-left:22px;font-size:11px;line-height:1.75}.doc-meta-title{font-size:25px;line-height:1.05;font-weight:900;color:var(--navy-dark);letter-spacing:.03em;margin:0 0 9px}.doc-meta-row{display:grid;grid-template-columns:105px 1fr;gap:8px}.doc-meta-row strong{color:var(--navy)}
.info-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:8px 0 18px}.info-box{border:1px solid var(--line);border-radius:10px;overflow:hidden;min-height:112px}.info-head{background:var(--soft);padding:10px 13px;font-size:12px;font-weight:900;color:var(--navy);text-transform:uppercase}.info-body{padding:12px 13px;font-size:12px;line-height:1.6}.customer-name{font-size:16px;font-weight:900;margin-bottom:2px}.invoice-table{width:100%;border-collapse:separate;border-spacing:0;border:1px solid var(--line);border-radius:9px;overflow:hidden;margin-top:8px}.invoice-table th{background:var(--navy);color:#fff;text-align:left;padding:10px 9px;font-size:11px;text-transform:uppercase}.invoice-table td{padding:12px 9px;border-bottom:1px solid var(--line);border-right:1px solid #e8eef5;font-size:12px;vertical-align:top}.invoice-table tr:last-child td{border-bottom:0}.invoice-table td:last-child,.invoice-table th:last-child{border-right:0}.sno{width:50px;text-align:center}.desc{width:48%}.qty{width:12%;text-align:right;white-space:nowrap}.amount{width:20%;text-align:right;white-space:nowrap;font-weight:900}.service-title{font-size:13px;font-weight:900;color:#172b48;margin-bottom:4px}.service-detail{font-size:10.5px;color:#5d6d81;line-height:1.45}.totals{width:45%;margin-left:auto;margin-top:16px;font-size:12px}.total-row{display:grid;grid-template-columns:1fr 140px;gap:12px;padding:5px 0}.total-row span:last-child{text-align:right}.total-row.grand{border-top:1px solid #aab8c8;margin-top:5px;padding-top:10px;font-size:16px;font-weight:900;color:var(--navy-dark)}.grand-value{background:var(--navy);color:#fff!important;border-radius:6px;padding:8px 10px;text-align:center!important}.foot{margin-top:18px;padding-top:12px;border-top:1px dashed #aebccd;color:#65758b;font-size:9.5px;line-height:1.45}.thanks{text-align:center;margin-top:12px;font-size:10px;color:#52647b}.incomplete{margin:12px 0;padding:10px 12px;border:1px solid #efd28a;background:#fff8e3;color:#805c0b;border-radius:8px;font-size:11px}@page{size:A4 portrait;margin:0}@media print{body{background:#fff}.actions{display:none}.sheet{margin:0;box-shadow:none;width:210mm;min-height:297mm;padding:12mm 12mm 10mm}}
</style>
</head>
<body>
<div class="actions"><button class="btn" onclick="window.print()">Print / Save PDF</button></div>
<div class="sheet">
<header class="doc-header"><div class="logo-wrap">@if($company?->logo_data_uri)<img src="{{ $company->logo_data_uri }}" alt="{{ $company->name }} logo">@else<div class="logo-fallback">ET</div>@endif</div><div><div class="brand-name">{{ $company?->name ?: 'Easy Ticket' }}</div><div class="brand-legal">{{ $company?->legal_name ?: 'Easy Group Of Travels' }}</div><div class="brand-contact">@if($branch?->name)<strong>{{ $branch->name }}</strong>@endif @if($branch?->address) · {{ $branch->address }}@elseif($company?->address) · {{ $company->address }}@endif<br>@if($branch?->phone){{ $branch->phone }}@elseif($company?->phone){{ $company->phone }}@endif</div></div><div class="doc-meta"><div class="doc-meta-title">QUOTATION</div><div class="doc-meta-row"><strong>Booking No.</strong><span>{{ $booking->booking_no }}</span></div><div class="doc-meta-row"><strong>Invoice Number</strong><span></span></div><div class="doc-meta-row"><strong>Booking Date</strong><span>{{ $booking->booking_date?->format('d M Y') }}</span></div><div class="doc-meta-row"><strong>Status</strong><span>PRICE CONFIRMATION</span></div></div></header>
<section class="info-grid"><div class="info-box"><div class="info-head">Customer</div><div class="info-body"><div class="customer-name">{{ $customer?->display_name ?: 'Customer' }}</div>@if($customer?->address_line_1)<div>{{ $customer->address_line_1 }}</div>@endif @if($customer?->city)<div>{{ $customer->city }}</div>@endif @if($customer?->mobile)<div>{{ $customer->mobile }}</div>@endif</div></div><div class="info-box"><div class="info-head">Quotation Details</div><div class="info-body"><div>Currency: <strong>{{ $document['currency'] }}</strong></div><div>Reference: <strong>{{ $booking->booking_no }}</strong></div><div>Invoice Number: <strong></strong></div></div></div></section>
@if(($document['commercial_completeness_status'] ?? '') !== 'COMPLETE')<div class="incomplete">This quotation is incomplete because one or more selected products have missing selling prices.</div>@endif
<table class="invoice-table"><thead><tr><th class="sno">S.No.</th><th class="desc">Description</th><th class="qty">Quantity</th><th class="amount">Amount ({{ $document['currency'] }})</th></tr></thead><tbody>@forelse($document['lines'] as $line)<tr><td class="sno">{{ $loop->iteration }}</td><td class="desc"><div class="service-title">{{ $line['product_description'] }}</div><div class="service-detail">{{ $line['product_type'] }} @if($line['service_dates']['from']) · {{ $line['service_dates']['from'] }}@endif @if($line['service_dates']['to']) → {{ $line['service_dates']['to'] }}@endif</div></td><td class="qty">{{ $line['quantity'] === null ? '—' : number_format((float)$line['quantity'],3) }}</td><td class="amount">{{ $line['line_selling_total'] === null ? '—' : number_format((float)$line['line_selling_total'],2) }}</td></tr>@empty<tr><td colspan="4" style="text-align:center;color:#66758a">No selected products.</td></tr>@endforelse</tbody></table>
<div class="totals"><div class="total-row"><span>Subtotal</span><span>{{ number_format((float)array_sum(array_map(fn($l)=>(float)($l['line_selling_total']??0),$document['lines'])),2) }}</span></div>@if($document['discounts'])<div class="total-row"><span>Discount</span><span>{{ number_format((float)array_sum(array_column($document['discounts'],'amount')),2) }}</span></div>@endif<div class="total-row grand"><span>Grand Total</span><span class="grand-value">{{ $document['currency'] }} {{ number_format((float)$document['grand_total'],2) }}</span></div></div>
<div class="foot">This quotation is for price confirmation only and is not a tax invoice or payment receipt.</div><div class="thanks">Thank you for choosing <strong>{{ $company?->name ?: 'Easy Ticket' }}</strong>.</div>
</div></body></html>
